// FUNCTION: BFME2 0x0060F560 size=490 name=?Save_Registry_Values@RegistryClass@@CAXPAXPADPAVINIClass@@@Z evidence=N:ledger
void RegistryClass::Save_Registry_Values(void *key, char *path, INIClass *ini)
{
	unsigned char data[8192];
	char value_name[256];
	char temp[512];

	int index = 0;
	LONG result;
	do {
		DWORD type = 0;
		DWORD data_size = sizeof(data);
		DWORD name_size = sizeof(value_name);
		result = RegEnumValue((HKEY)key, index, value_name, &name_size, 0, &type, data, &data_size);
		if (result == ERROR_SUCCESS) {
			switch (type) {
				case REG_SZ:
					strcpy(temp, "STRING_");
					strcat(temp, value_name);
					ini->Put_String(path, temp, (char *)data);
					break;

				case REG_BINARY:
					strcpy(temp, "BIN_");
					strcat(temp, value_name);
					ini->Put_UUBlock(path, temp, data, data_size);
					break;

				case REG_DWORD:
					strcpy(temp, "DWORD_");
					strcat(temp, value_name);
					ini->Put_Int(path, temp, *(int *)data, 0);
					break;
			}
		}
		index++;
	} while (result == ERROR_SUCCESS);
}

// FUNCTION: BFME2 0x0060F750 size=454 name=?Save_Registry_Tree@RegistryClass@@CAXPADPAVINIClass@@@Z evidence=N:ledger
void RegistryClass::Save_Registry_Tree(char *path, INIClass *ini)
{
	HKEY base_key;
	HKEY sub_key;
	int index = 0;
	char name[256];
	unsigned long name_size = sizeof(name);
	char class_name[256];
	unsigned long class_name_size = sizeof(class_name);
	FILETIME file_time;
	memset(&file_time, 0, sizeof(file_time));

	long result = RegOpenKeyEx(HKEY_LOCAL_MACHINE, path, 0, KEY_ALL_ACCESS, &base_key);

	if (result == ERROR_SUCCESS) {

		Save_Registry_Values(base_key, path, ini);

		while (result == ERROR_SUCCESS) {
			class_name_size = sizeof(class_name);
			name_size = sizeof(name);
			result = RegEnumKeyEx(base_key, index, name, &name_size, 0, class_name, &class_name_size, &file_time);
			if (result == ERROR_SUCCESS) {

				/*
				** See if there are sub keys.
				*/
				char new_key_path[512];
				strcpy(new_key_path, path);
				strcat(new_key_path, "\\");
				strcat(new_key_path, name);

				unsigned long num_subs = 0;
				unsigned long num_values = 0;

				long new_result = RegOpenKeyEx(HKEY_LOCAL_MACHINE, new_key_path, 0, KEY_ALL_ACCESS, &sub_key);
				if (new_result == ERROR_SUCCESS) {
					new_result = RegQueryInfoKey(sub_key, 0, 0, 0, &num_subs, 0, 0, &num_values, 0, 0, 0, 0);

					/*
					** If there are sun keys then enumerate those.
					*/
					if (num_subs > 0) {
						Save_Registry_Tree(new_key_path, ini);
					}

					if (num_values > 0) {
						Save_Registry_Values(sub_key, new_key_path, ini);
					}
					RegCloseKey(sub_key);
				}
			}
			index++;
		}
		RegCloseKey(base_key);
	}
}

